255	// ================================================================ N1 Month track, BẢN C4 (S21–S24) — sửa lỗi CHÍNH của C3 (C3-answer câu 1: "lớp trả thêm không thấy bằng hình")
256	// bằng ĐỔI LOẠI HÌNH (không chỉ độ sáng): lớp trả thêm là TẤM NỔI có độ dày (0,075 ≈ ô bắt buộc), phủ 86 % mặt ô, cạnh bên thấy được từ góc 3/4,
257	// phát quang ink; mỗi cột-năm có tấm RƠI từ trên cao xuống (drop[c] ∈ [0,1], một nốt mỗi cột); ô bắt buộc TỐI HẲN xuống (ink-muted → xám đậm) khi
258	// tấm của cột tới (cover[c]) → tương phản tấm sáng / ô tối. Gom năm (S23): 12 tấm của cột trượt về ô thứ 12 và chồng thành khối 12 lớp CÓ KHE
259	// (SG = 0,03 giữa hai lớp → đếm được); màu lưới không đổi khi gom. Ô trễ (warn) to ×1,2 và cao ×2,5; vách 15 năm thấp (0,18) và trong mờ → không
260	// che ô trễ. Bóng lịch 30 năm (ghost): 15 cột mờ quá vách = phần khoản 30 năm còn chạy nếu chỉ trả mức bắt buộc (S22.1 "ends sooner").
261	export const TRK = { req: '#9AA4B2', dark: '#343A44', warn: '#F2B441', ink: '#F2F4F7', empty: '#2A303B' };
262	export function TrackC4({ n = 180, cols = 12, spare = 2, tile = 0.34, gap = 0.08, th = 0.07, slab = 0.075, SG = 0.03, SF = 0.86, DROP = 1.3, name = 'tessa' } = {}) {
263	  const g = new THREE.Group(), pitch = tile + gap, years = Math.ceil(n / cols), nmax = n + spare * cols;
264	  const mat = (c, o = {}) => new THREE.MeshStandardMaterial({ color: c, roughness: 0.8, transparent: true, ...o });
265	  const tiles = new THREE.InstancedMesh(new THREE.BoxGeometry(tile, th, tile), mat('#FFFFFF'), nmax);
266	  const slabs = new THREE.InstancedMesh(new THREE.BoxGeometry(tile * SF, slab, tile * SF), mat(TRK.ink, { emissive: new THREE.Color(TRK.ink), emissiveIntensity: 0.85 }), n);
267	  const ghost = new THREE.InstancedMesh(new THREE.BoxGeometry(tile, 0.014, tile), mat(TRK.req, { opacity: 0.3, depthWrite: false }), n);
268	  for (const m of [tiles, slabs]) { m.castShadow = m.receiveShadow = true; m.frustumCulled = false; g.add(m); }
269	  ghost.frustumCulled = false; g.add(ghost);
270	  const markX = years * pitch - gap / 2, depth = cols * pitch - gap;
271	  const mark = new THREE.Mesh(new THREE.BoxGeometry(0.05, 0.18, depth + 0.5), mat(TRK.req, { emissive: new THREE.Color(TRK.req), emissiveIntensity: 0.4, depthWrite: false }));
272	  mark.position.set(markX, 0.09, -depth / 2 + tile / 2); g.add(mark);
273	  const pos = (i) => [Math.floor(i / cols) * pitch + tile / 2, -(i % cols) * pitch];
274	  const M = new THREE.Matrix4(), col = new THREE.Color(), K = { req: new THREE.Color(TRK.req), dark: new THREE.Color(TRK.dark), warn: new THREE.Color(TRK.warn), ink: new THREE.Color(TRK.ink), empty: new THREE.Color(TRK.empty) };
275	  const hide = new THREE.Matrix4().makeScale(0, 0, 0), cl = (x) => Math.min(1, Math.max(0, x)), sm = (u) => u * u * (3 - 2 * u);
276	  tiles.userData.checks = { role: 'mark', series: name, key: `track-${name}-tiles` };
277	  slabs.userData.checks = { role: 'mark', series: name, key: `track-${name}-extra` };
278	  mark.userData.checks = { role: 'mark', series: name, key: `track-${name}-mark` };
279	  g.userData = { n, cols, pitch, tile, th, years, nmax, markX, depth, slab, SG };
280	  const zEnd = pos(cols - 1)[1], arr = (v, c) => (Array.isArray(v) ? v[c] || 0 : typeof v === 'function' ? v(c) : cl(v - c));
281	  // lit, late: như obj7 (số ô thực); flash/cover/drop/gathered: mảng theo cột (hoặc số thực "số cột từ trái"); lift = {i, a}: tấm tháng i nhấc lên (S22.3);
282	  // bob(i) → độ nảy của tấm tháng i (S23: sóng "mỗi tháng một lớp"); ghost = số cột bóng 30 năm (thực), ghostA; markA
283	  g.set = ({ lit = n, late = 0, flash = 0, cover = 0, drop = 0, gathered = 0, lift = null, bob = null, ghost: gc = 0, ghostA = 0, markA = 1, pulse = 0 } = {}) => {
284	    for (let i = 0; i < nmax; i++) {
285	      const [x, z] = pos(i), isLate = i >= n, c = Math.floor(i / cols), a = isLate ? cl(late - (i - n)) : cl(lit - i);
286	      if (a <= 0.002) { tiles.setMatrixAt(i, hide); continue; }
287	      if (isLate) { M.makeScale(1.2, 2.5, 1.2).setPosition(x, th * 2.5 / 2, z); col.copy(K.empty).lerp(K.warn, a * (0.85 + 0.15 * pulse)); }
288	      else { M.makeScale(1, a, 1).setPosition(x, th * a / 2, z); col.copy(K.req).lerp(K.dark, arr(cover, c)).lerp(K.ink, 0.8 * arr(flash, c)); }
289	      tiles.setMatrixAt(i, M); tiles.setColorAt(i, col);
290	    }
291	    for (let i = 0; i < n; i++) {
292	      const c = Math.floor(i / cols), r = i % cols, d = arr(drop, c) * cl(lit - i), [x, z] = pos(i);
293	      if (d <= 0.002) { slabs.setMatrixAt(i, hide); continue; }
294	      const k = cols - 1 - r, dl = 0.35 * k / (cols - 1), e = sm(cl((arr(gathered, c) - dl) / (1 - dl))), fall = sm(d);
295	      const y0 = th + slab / 2 + 0.004, y1 = th + 0.004 + k * (slab + SG) + slab / 2;
296	      let y = y0 + (y1 - y0) * e + 0.08 * Math.sin(Math.PI * e) + (1 - fall) * DROP;
297	      if (bob) y += bob(i); if (lift && lift.i === i) y += 1.1 * lift.a;
298	      M.makeScale(1, 1, 1).setPosition(x, y, z + (zEnd - z) * e); slabs.setMatrixAt(i, M);
299	    }
300	    for (let i = 0; i < n; i++) {
301	      const c = Math.floor(i / cols), a = cl(gc - c) * ghostA;
302	      if (a <= 0.002) { ghost.setMatrixAt(i, hide); continue; }
303	      const [x, z] = pos(i + n); M.makeScale(1, 1, 1).setPosition(x, 0.007, z); ghost.setMatrixAt(i, M);
304	    }
305	    for (const m of [tiles, slabs, ghost]) m.instanceMatrix.needsUpdate = true;
306	    if (tiles.instanceColor) tiles.instanceColor.needsUpdate = true;
307	    ghost.material.opacity = 0.3 * Math.min(1, ghostA); ghost.visible = ghostA > 0.01 && gc > 0;
308	    mark.material.opacity = 0.5 * markA; mark.visible = markA > 0.01;
309	    tiles.userData.checks.level = +Math.min(n, lit).toFixed(2); tiles.userData.checks.late = +late.toFixed(2);
310	  };
311	  g.blockTop = (c) => { const [x, z] = pos(c * cols + cols - 1); return [g.position.x + x, g.position.y + th + cols * (slab + SG), g.position.z + z]; };
312	  g.tileAt = (i) => { const [x, z] = pos(i); return [g.position.x + x, g.position.y + th, g.position.z + z]; };
313	  g.colX = (c, side = 0) => g.position.x + c * pitch + (side < 0 ? 0 : side > 0 ? tile : tile / 2);
314	  g.frontZ = () => g.position.z + tile / 2;
315	  g.backZ = () => g.position.z - (cols - 1) * pitch - tile / 2;
316	  g.markWorldX = () => g.position.x + markX;
317	  g.set({});
318	  return g;
319	}
320	
321	// ================================================================ S22.2 một khoản trả bắt buộc tách hai phần (lãi dưới, ink-muted đậm · gốc trên, ink): tổng cao CỐ ĐỊNH
322	// (khoản bắt buộc không đổi), phần lãi co lại theo tháng khi trả thêm → "next month's interest ↓, payment fixed". set({share, a}) share = phần lãi ∈ [0,1]
323	export function SplitBar({ x, z, h = 2.0, w = 0.55, d = 0.4 } = {}) {
324	  const g = new THREE.Group(), mk = (c, e) => new THREE.Mesh(new THREE.BoxGeometry(w, 1, d), new THREE.MeshStandardMaterial({ color: c, roughness: 0.7, transparent: true, emissive: new THREE.Color(c), emissiveIntensity: e }));

