1	// Tập 7 · C4 · ĐOẠN F = S25–S28. the bar (bản C3 s25-bar + sửa C4): tờ đô la trả thêm từ tay Tessa chạm chỗ cạnh nhà đúng "charged", thanh (W3, ink-muted)
2	// trồi từ sàn rồi dâng tới độ cao lãi → đồ thị: THANG ĐỘ CAO có khắc (sàn → thanh), ba khối chữ (the bar · interest… · not tested…), bóng "any other use"
3	// lên xuống LIÊN TỤC qua độ cao thanh (không dừng ngang mép), nhãn đi theo bóng, vạch "đo" ngang → lia sang lịch sử lãi 30 năm (cùng thang): đoạn
4	// thanh cưỡi đầu đường, đỉnh 9.25% Nov 1994, đáy 2.65% Jan 2021 → vạch độ cao thanh của Tessa qua cả lịch sử: đoạn cao hơn sáng (≈ 1 tuần trong 5).
5	import { setup, figure, gesture, figTag, modeLook, followLight, chrome, SRC, SRC_SIM, label, seg2, dip,
6	  kf, show, pulse, C, ease, lin, mix, THREE, setOpacity } from '/episodes/ep007/world/c4kit.js';
7	import { Beam, Ribbon } from '/toolkit/factory/world/lib3d.js';
8	import { Bill } from '/episodes/ep007/world/obj7.js';
9	
10	const SEG = '/episodes/ep007/world/c4/f-s25-s28/';
11	const PER_PCT = 0.3;                    // độ cao thế giới mỗi điểm % (C3)
12	const BOB = 0.45, BOB_T = 2.4;          // bóng: biên độ ĐỦ ngay từ đầu (đỉnh/đáy cách mép thanh ±1,5 điểm), chu kỳ
13	
14	export async function boot(res) {
15	  const poses = {
16	    wB: { pos: [-4.6, 2.5, 7.6], tgt: [-0.4, 1.0, 0], fov: 38, chart: 0 },
17	    cB: { pos: [0.1, 1.45, 18], tgt: [0.1, 1.45, 0], fov: 19, chart: 1 },
18	    cH: { pos: [3.7, 2.2, 27.5], tgt: [3.7, 2.2, 0], fov: 20, chart: 1 },
19	  };
20	  const { S, D, G, cue, MV, st, O, renderer, scene, floor, key, CAM } = await setup(SEG, res, poses);
21	  const b = cue, X = S.x, BX = X.bx, BL = X.bl, GX = BX + BL / 2 + 1.2, N = S.r30.length;
22	  const hm = figure(scene, { x: X.house });
23	  const beam = Beam({ length: BL }); beam.scale.set(1, 2.2, 1.4); scene.add(beam); beam.userData.checks = { role: 'mark', series: 'bar', key: 'the-bar' };
24	  const rider = Beam({ length: 0.7 }); rider.scale.set(1, 2.2, 1.4); scene.add(rider); rider.userData.checks = { role: 'mark', series: 'bar', key: 'bar-rider' };
25	  const d1 = Bill({ name: 'extra-dollar' }), d2 = Bill({ name: 'any-other-use' }); scene.add(d1, d2);
26	  setOpacity(d2, 0.28);
27	  const hand = [hm.person.position.x + 0.35, 0.62, hm.person.position.z + 0.15], [land0, land1] = S.dollar1.place;
28	  const hx = (i) => X.h0 + (i + 0.5) * (X.h1 - X.h0) / N;
29	  const line = Ribbon({ color: C.accent, z: 0.1, width: 0.06, maxPts: N }); scene.add(line); line.userData.checks = { role: 'series', series: 'r30', key: 'rate-30-history' };
30	
31	  function frame(t) {
32	    const pose = CAM.apply(t), cw = pose.chart, cam = CAM.cam;
33	    followLight(key, pose.tgt); modeLook(scene, floor, cw); gesture(hm, t, S.gestures);
34	    // thanh: sàn trống tới "charged"; trồi đúng "charged" (0,25 s), dâng tới độ cao lãi ở "rate"
35	    const up = ease(t, b.a0.charged - 0.02, b.a0.charged + 0.23), Hb = kf(S.bar, t) * PER_PCT, H = -0.12 + (0.12 + Math.max(0.06, Hb)) * up;
36	    beam.position.set(BX, H, 0); beam.visible = up > 0.01; beam.userData.checks.value = +kf(S.bar, t).toFixed(3);
37	    beam.glow(0.6 * Math.max(pulse(t, b.a3.bar, 1.0), pulse(t, b.b0.taken, 1.0), pulse(t, b.b3.tessa, 1.2)), C.ink);
38	    // tờ 1: trong tay Tessa → bay vòng, CHẠM mặt thanh đúng "charged", cưỡi theo thanh
39	    const a1 = show(t, S.dollar1.appear), x1 = ease(t, land0, land1), top = [BX - 0.5, Math.max(H, 0.06) + 0.22, 0];
40	    d1.rotation.x = (Math.PI / 2) * Math.max(x1, 0.35);
41	    d1.position.set(mix(hand[0], top[0], x1), mix(hand[1], top[1], x1) + 1.0 * Math.sin(Math.PI * x1), mix(hand[2], top[2], x1) + 1.0 * Math.sin(Math.PI * x1));
42	    d1.scale.setScalar(Math.max(0.001, a1)); d1.visible = a1 > 0.01;
43	    // tờ 2 (bóng): hiện tại chỗ ở "other", lên xuống LIÊN TỤC với biên độ đủ ngay từ đầu (qua độ cao thanh ở tốc độ lớn nhất, đứng lại chỉ ở đỉnh/đáy
44	    // cách mép ±1,5 điểm); mờ đi khi lia sang lịch sử — vẫn đang chuyển động
45	    const a2 = show(t, S.dollar2.appear) * (1 - ease(t, MV.m_pan.t0, MV.m_pan.t0 + 0.8)), bob = BOB * Math.sin((2 * Math.PI * (t - S.dollar2.appear)) / BOB_T);
46	    const p2 = [GX, Hb + bob, 0.05];
47	    d2.rotation.x = Math.PI / 2; d2.position.set(...p2); d2.scale.setScalar(Math.max(0.001, a2)); d2.visible = a2 > 0.01;
48	    // S26: lịch sử lãi 30 năm (cùng thang 0,3/điểm), vẽ ở "moves"; đoạn thanh ngắn cưỡi đầu đường rồi đứng ở tuần cuối; S28 đoạn cao hơn sáng
49	    const dr = lin(t, b.b0.moves, b.b0.moves + 1.4) * (N - 1), m = Math.floor(dr), fw = t > b.b3.only + 0.3;
50	    const pts = []; for (let i = 0; i <= m; i += 2) pts.push([hx(i), S.r30[i] * PER_PCT, fw ? (S.r30[i] >= G.bar - 1e-9 ? '#A9C6FF' : '#2B4470') : C.accent]);
51	    if (m < N - 1 && dr > m) pts.push([hx(dr), mix(S.r30[m], S.r30[m + 1], dr - m) * PER_PCT]);
52	    if (pts.length > 1) line.set(pts); line.visible = pts.length > 1;
53	    const cr = Math.min(N - 1, dr), ry = (Math.floor(cr) < N - 1 ? mix(S.r30[Math.floor(cr)], S.r30[Math.ceil(cr)], cr - Math.floor(cr)) : S.r30[N - 1]) * PER_PCT;
54	    rider.position.set(hx(cr), ry, 0.12); rider.visible = dr > 0; rider.glow(0.6 * pulse(t, b.b0.taken, 1.0), C.ink);
55	    renderer.render(scene, cam);
56	    // ---------------- lớp phủ
57	    const log = O.begin(t, cw, cam), ok = cw >= 0.95 ? 1 : 0; log.roi = {};
58	    dip(O, 1 - ease(t, 0, 0.4));   // mở hồi 3 sau khoảng giữ MR2
59	    figTag(O, hm);
60	    const sc = (x, y, z = 0) => O.toScreen(x, y, z), s25 = MV.m_pan.t0 - 0.05;
61	    const [bx0, by] = sc(BX - BL / 2, Hb, 0), [bx1] = sc(BX + BL / 2, Hb, 0), [, fy] = sc(BX, 0, 0), bc = (bx0 + bx1) / 2;
62	    { const [x, y] = sc(...hand); log.roi['a0.dollar'] = [x - 80, y - 80, x + 80, y + 80]; }
63	    log.roi['a0.charged'] = [bx0 - 20, by - 40, bx1 + 20, fy + 10];
64	    // THANG ĐỘ CAO: vạch đo đứng ink-muted từ sàn tới thanh, KHẮC mỗi điểm % (khắc dài mỗi 5 điểm), khắc đỉnh ở thanh — không chữ
65	    { const [dx] = sc(BX - BL / 2 - 0.22, 0, 0), a = ok * (t < s25 + 0.3 ? 1 - ease(t, s25, s25 + 0.3) : 0), c = O.ctx;
66	      if (a > 0.01) { c.save(); c.globalAlpha = a; c.strokeStyle = C.muted; c.lineWidth = 4; c.beginPath(); c.moveTo(dx, fy); c.lineTo(dx, by);
67	        for (let k = 0; k <= Math.floor(G.bar); k++) { const [, yk] = sc(BX, k * PER_PCT, 0), w = k % 5 === 0 ? 20 : 11; c.moveTo(dx - w, yk); c.lineTo(dx + w, yk); }
68	        c.moveTo(dx - 16, by); c.lineTo(bx0 - 4, by); c.stroke(); c.restore(); }
69	      log.roi['a1.scale'] = [dx - 30, by - 10, dx + 30, fy + 10]; }
70	    // khối 1: the bar; khối 2: interest…; khối 3: not tested… (cột chữ dưới thanh, bên phải thước)
71	    label(O, `the bar: ${D('bar_now')}`, bc, by - 118, { align: 'center', kind: 'number', alpha: ok * show(t, b.a1.seven, s25), claims: ['bar_now'] });
72	    log.roi['a1.seven'] = [bc - 520, by - 182, bc + 520, by - 102];
73	    const XR = 820, i2 = ok * show(t, b.a2.investment, s25), n4 = ok * show(t, b.a4.whether, s25);
74	    label(O, 'interest no longer charged,', XR, by + 215, { kind: 'compare', px: 48, alpha: i2 });
75	    label(O, 'not an investment return', XR, by + 280, { kind: 'compare', px: 48, alpha: i2 });
76	    log.roi['a2.investment'] = [XR - 10, by + 165, XR + 700, by + 300];
77	    label(O, 'not tested: how any investment compares,', XR, by + 365, { kind: 'compare', px: 48, alpha: n4 });
78	    label(O, 'once risk and taxes count', XR, by + 430, { kind: 'compare', px: 48, alpha: n4 });
79	    log.roi['a4.whether'] = [XR - 10, by + 315, 1840, by + 450];
80	    log.roi['a3.bar'] = [bx0 - 20, by - 40, bx1 + 20, by + 40];
81	    // bóng: viền nét đứt (cùng cỡ tờ thật) + nhãn "any other use" ĐI THEO bóng (ngay dưới bóng)
82	    const [gx, gy] = sc(...p2);
83	    if (a2 > 0.01) {
84	      const q = [[-0.31, -0.14], [0.31, -0.14], [0.31, 0.14], [-0.31, 0.14]].map(([u, v]) => sc(p2[0] + u * a2, p2[1] + v * a2, p2[2] + 0.02)), c = O.ctx;
85	      c.save(); c.globalAlpha = a2; c.strokeStyle = C.ink; c.lineWidth = 3; c.setLineDash([9, 7]); c.beginPath();
86	      q.forEach(([x, y], i) => (i ? c.lineTo(x, y) : c.moveTo(x, y))); c.closePath(); c.stroke(); c.restore();
87	    }
88	    label(O, 'any other use', gx, gy + 84, { align: 'center', kind: 'name', px: 48, alpha: a2 });
89	    { const [x0, y0] = sc(GX - 0.5, Hb + BOB + 0.3, 0), [x1, y1] = sc(GX + 0.5, Hb - BOB - 0.3, 0); log.roi['a3.other'] = [x0, y0, x1, y1]; }
90	    // "measured": vạch nét đứt ngang độ cao thanh, từ đầu thanh tới chỗ bóng (phép đo)
91	    { const [gx1] = sc(GX + 0.35, Hb, 0), a = ok * show(t, b.a3.measured, s25);
92	      seg2(O, bx1 + 6, by, mix(bx1 + 6, gx1, lin(t, b.a3.measured - 0.05, b.a3.measured + 0.4)), by, C.ink, 0.85 * a, 3, [12, 9]);
93	      log.roi['a3.measured'] = [bx1, by - 30, gx1 + 10, by + 30]; }
94	    // S26–S28: lịch sử
95	    const [h0x, hy0] = sc(X.h0, 0, 0.1), [h1x] = sc(X.h1, 0, 0.1);
96	    log.roi['b0.moves'] = [h0x, sc(0, 3.0)[1], h1x, hy0]; log.roi['b0.taken'] = log.roi['b0.moves'];
97	    const mk = (i, at, z, s, cl, lx, ly, align) => {
98	      const [x, y] = sc(hx(i), S.r30[i] * PER_PCT, 0.1), a = ok * show(t, at, z), c = O.ctx;
99	      if (a > 0.01) { c.save(); c.globalAlpha = a; c.fillStyle = C.ink; c.beginPath(); c.arc(x, y, 10, 0, 7); c.fill(); c.restore(); }
100	      seg2(O, x, y + (ly < y ? -14 : 14), x, ly + (ly < y ? 14 : -50), C.ink, 0.8 * a, 3);
101	      return [x, y];
102	    };
103	    { const [x, y] = mk(S.i.max, b.b1.high, b.b3.only - 0.1, '', null, 0, 410);
104	      label(O, `highest: ${D('r30_max')} · ${D('r30_max_week_short')}`, Math.max(500, x), 392, { align: 'center', kind: 'number', alpha: ok * show(t, b.b1.nine, b.b3.only - 0.1), claims: ['r30_max', 'r30_max_week_short'] });
105	      log.roi['b1.high'] = [x - 30, y - 30, x + 30, y + 30]; log.roi['b1.nine'] = [x - 380, 340, x + 380, 410]; }
106	    { const [x, y] = mk(S.i.min, b.b2.low, b.b3.only - 0.1, '', null, 0, 800);
107	      label(O, `lowest: ${D('r30_min')} · ${D('r30_min_week_short')}`, 1810, 790, { align: 'right', kind: 'number', alpha: ok * show(t, b.b2.two, b.b3.only - 0.1), claims: ['r30_min', 'r30_min_week_short'] });
108	      log.roi['b2.low'] = [x - 30, y - 30, x + 30, y + 30]; log.roi['b2.two'] = [1100, 740, 1810, 805]; }
109	    // S28: vạch độ cao thanh của Tessa qua cả lịch sử (nối từ đầu thanh)
110	    { const [ex, ey] = sc(BX + BL / 2, G.bar * PER_PCT, 0.1), a = ok * show(t, b.b3.only);
111	      seg2(O, ex + 4, ey, mix(ex + 4, h1x, lin(t, b.b3.only, b.b3.only + 0.6)), ey, C.muted, 0.9 * a, 4, [14, 10]);
112	      log.roi['b3.only'] = [ex, ey - 40, h1x, ey + 40]; }
113	    label(O, `weeks with a bar this high: ${D('share_r30_ge_now')}`, 960, 205, { align: 'center', kind: 'number', alpha: ok * show(t, b.b3.one), claims: ['share_r30_ge_now'] });
114	    log.roi['b3.one'] = [300, 150, 1620, 230];
115	    { const [x, y] = sc(BX, Hb, 0); log.roi['b3.tessa'] = [x - 200, y - 40, x + 200, y + 40]; }
116	    chrome(O, { src: t < MV.m_pan.t0 ? SRC_SIM(D) : SRC });
117	    st.compose(); log.camMoving = CAM.moving(t); return log;
118	  }
119	  return { canvas: st.out, frame };
