      log.roi['b1.high'] = [x - 30, y - 30, x + 30, y + 30]; log.roi['b1.nine'] = [x - 380, 340, x + 380, 410]; }
    { const [x, y] = mk(S.i.min, b.b2.low, b.b3.only - 0.1, '', null, 0, 800);
